<script setup>
import ChevronText from '../../Components/ChevronText.vue';
import { useI18n } from "../../lib/i18n.js";
const {t}=useI18n();
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import Errors from '../../Components/Errors.vue';
defineProps({googleEnabled:{type:Boolean,default:false}});
const page=usePage();
const form=useForm({name:'',email:'',password:'',password_confirmation:''});
const google=useForm({remember:false});
function submitGoogle(){if(form.processing||google.processing)return;google.post('/auth/google/redirect');}
const submit=()=>{if(form.processing||google.processing)return;form.post('/register',{onFinish:()=>form.reset('password','password_confirmation')});};
</script>
<template><Head :title="t('Create your space')"/><div class="auth-shell"><section class="auth-story"><div class="brand"><span class="brand-symbol">v.</span>vocamilo</div><div><span class="pill">{{t("A SPACE FOR YOUR WORDS")}}</span><h1>{{t("Curiosity")}}<br>{{t("looks good")}}<br>{{t("on you.")}}</h1><p>{{t("Collect what matters. Practice what you want to remember.")}}</p></div><div class="auth-decoration">{{t("Your learning starts here.")}}</div></section><main class="auth-form"><div class="eyebrow">{{t("LET'S GET STARTED")}}</div><h1>{{t("Create your space.")}}</h1><p class="muted">{{t("A personal word pool, ready to grow.")}}</p><p v-if="page.props.errors?.google" class="notice error" role="alert">{{t(page.props.errors.google)}}</p><label v-if="googleEnabled" class="remember-choice"><input v-model="google.remember" type="checkbox" :disabled="form.processing||google.processing"/><span>{{t("Keep me signed in with Google")}}</span></label><Errors :errors="google.errors"/><button v-if="googleEnabled" type="button" class="button secondary google-signin" :disabled="form.processing||google.processing" @click="submitGoogle">{{google.processing?t("Signing in…"):t("Continue with Google")}}</button><p v-if="googleEnabled" class="muted small">{{t("Or continue with your email and password")}}</p><form @submit.prevent="submit"><Errors :errors="form.errors"/><label>{{t("Name")}}<input id="register-name" name="name" v-model="form.name" type="text" required maxlength="100" autocomplete="name"/></label><label>{{t("Email")}}<input id="register-email" name="email" v-model="form.email" type="email" required autocomplete="email"/></label><label>{{t("Password (at least 10 characters)")}}<input id="register-password" name="password" v-model="form.password" type="password" required minlength="10" autocomplete="new-password"/></label><label>{{t("Confirm password")}}<input id="register-password-confirmation" name="password_confirmation" v-model="form.password_confirmation" type="password" required autocomplete="new-password"/></label><button class="button" :disabled="form.processing||google.processing"><ChevronText :text="form.processing?t('Creating…'):t('Create account →')"/></button></form><p class="auth-switch">{{t("Already learning here?")}} <Link href="/login">{{t("Sign in")}}</Link></p></main></div></template>

<style scoped>.remember-choice{display:flex;flex-direction:row;align-items:center;gap:12px;cursor:pointer;line-height:1.5}.remember-choice input{width:18px;height:18px;flex:0 0 18px;margin:0;accent-color:var(--teal,#157e73)}.remember-choice span{min-width:0}.remember-choice input:focus-visible{outline:3px solid #45baa8;outline-offset:3px}.google-signin{width:100%;min-height:46px}</style>
